using Marten.Events.Projections.Flattened;   // FlatTableProjection AND SchemaNameSource
using Campaigns.Contracts;

namespace Campaigns.Views;

/// <summary>
/// Context: campaigns. Slice: message-metrics. Fed by MessageQueued, MessageDelivered, MessageBounced.
///
/// RECIPE 6: a FlatTableProjection — a read model that is a SQL TABLE, not a document.
///
/// Deliberately the SAME GRAIN as MessageStatus (identity="messageId"), because the duplication is the
/// comparison. MessageStatus is a JSONB document you load by id; this is columns you can GROUP BY. Nothing
/// in the model distinguishes them — the drawing is identical — which is the point of this whole folder:
/// <c>Event(s) → View</c> does not choose the storage.
///
/// When it earns its keep: "delivery rate by campaign by day", "the ten worst senders this month". Those
/// are aggregations ACROSS rows, and a document store answers them by loading every row into memory.
/// Postgres answers them in the database.
///
/// There is no <c>MessageMetrics</c> C# type. That is not an omission — the read model IS the table, and
/// inventing a class to mirror it would be a second place the same schema lives. Readers write SQL; the
/// test does exactly that.
///
/// THREE THINGS LEARNED HERE, all of them costs rather than surprises:
///
/// 1. <c>Map</c> TAKES A MEMBER, SO A DERIVED COLUMN IS NOT EXPRESSIBLE. The model declares
///    <c>recipientCount</c>, derived by counting <c>recipients</c>. <c>Map(x =&gt; x.Recipients.Length)</c>
///    is not a member of the event, and the declarative API has no Compute. So the column is dropped here
///    and the count is left to <c>count(*)</c> over DeliveryLog, or to MessageStatus. Marten's own docs
///    point at EventProjection + <c>QueueSqlCommand</c> for cases the declarative API cannot express —
///    that is a seventh recipe, and choosing it would mean writing the upsert SQL by hand.
///    **This is a real gap between the model and the recipe, and the model is not wrong.** It says what a
///    row holds; this recipe cannot hold all of it.
/// 2. <c>Increment</c> generates an UPDATE-only function for an event that does not populate every
///    non-primary-key column. So MessageDelivered and MessageBounced cannot create a half-populated row,
///    and if one arrives before MessageQueued it is a silent no-op. The stream must start with the
///    full-mapping event — which the model guarantees, since MessageQueued opens every Message stream.
/// 3. Column names are snake_cased from the member by default. Spelling them out is worth it once: the
///    test's SQL has to name them, and a silent rename between Marten's convention and a hand-written
///    query is a bug that only shows up as a column-not-found at runtime.
/// </summary>
public sealed class MessageMetricsProjection : FlatTableProjection
{
    public const string TableName = "message_metrics";

    public MessageMetricsProjection() : base(TableName, SchemaNameSource.EventSchema)
    {
        // The primary key is the stream id, which for the Message stream IS the messageId.
        Table.AddColumn<Guid>("id").AsPrimaryKey();

        // Marten manages this table's migration, so a rebuild has something to truncate.
        Options.TeardownDataOnRebuild = true;

        // The full-mapping event: it populates every non-PK column, so it is the only one that can
        // CREATE a row. See note 2.
        Project<MessageQueued>(map =>
        {
            map.Map(x => x.CampaignId, "campaign_id");
            map.Map(x => x.SenderId, "sender_id");
            map.Map(x => x.QueuedAt, "queued_at");
            map.SetValue("delivered", 0);
            map.SetValue("bounced", 0);
        });

        // Partial-mapping events: UPDATE-only, so they can never invent a row.
        Project<MessageDelivered>(map => map.Increment("delivered"));
        Project<MessageBounced>(map => map.Increment("bounced"));
    }
}
